INSERT INTO categories (id, label, description, sort_order) VALUES ('stickers', 'Calcos y stickers', 'Calcos individuales con personajes y gráficas originales: criaturas, autos, fútbol de barrio, música y cultura gamer. Pensados para laptops, botellas, cuadernos y cascos.', 0);
INSERT INTO categories (id, label, description, sort_order) VALUES ('packs', 'Packs', 'Combinaciones de stickers agrupados por temática. Una forma de probar varios diseños de una sola vez y armar tu propia composición.', 1);
INSERT INTO categories (id, label, description, sort_order) VALUES ('indumentaria', 'Indumentaria', 'Remeras negras y claras con estampas originales de la marca. Los talles, telas y técnicas de estampado definitivos todavía están por confirmarse.', 2);
INSERT INTO categories (id, label, description, sort_order) VALUES ('dtf', 'DTF', 'Planchas con varios diseños dispuestos para impresión por transferencia (DTF). En esta demo se muestran como referencia visual.', 3);
INSERT INTO categories (id, label, description, sort_order) VALUES ('vinilos', 'Vinilos', 'Vinilos decorativos para paredes y kits de calcos para laptops, cascos y otros objetos. Las medidas reales se definirán junto con el catálogo comercial.', 4);
INSERT INTO categories (id, label, description, sort_order) VALUES ('personalizados', 'Personalizados', 'Stickers, etiquetas y prendas hechas a partir de tu diseño o referencia. Se cotizan a pedido: en esta demo, el formulario es solo una simulación.', 5);
INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p08', 'pack-caos-grafico', 'Pack Caos Gráfico', 'Ocho piezas para llenar cualquier superficie: ojo, rayo, llama, smile mutante y más gráficas de la casa.', 'packs', NULL, false, 'active', ARRAY['pack', 'gráfico', 'urbano']::text[]);
INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p09', 'pack-tribuna', 'Pack Tribuna', 'Pelota, bufanda, camiseta 10, copa y frases de cancha. Sin escudos oficiales: pura tribuna genérica.', 'packs', NULL, false, 'active', ARRAY['fútbol', 'pack', 'tribuna']::text[]);
INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p10', 'pack-pixel-punk', 'Pack Pixel Punk', 'Criatura pixelada, joystick, robot, ovni y corazón de 8 bits. Seis piezas para tu setup.', 'packs', NULL, false, 'active', ARRAY['gaming', 'pixel', 'pack']::text[]);
INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p11', 'pack-garage', 'Pack Garage', 'Auto, casco, llama, rayo y frases de ruta. Seis calcos para cascos, motos y cajas de herramientas.', 'packs', NULL, false, 'active', ARRAY['motos', 'autos', 'pack']::text[]);
INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p12', 'pack-kawaii-kaos', 'Pack Kawaii Kaos', 'Personajes tiernos con mala actitud: ronin, onigiri, cometa, gato mutante y cohete.', 'packs', NULL, false, 'active', ARRAY['anime', 'kawaii', 'pack']::text[]);
