INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p14', 'remera-otro-planeta', 'Remera Otro Planeta', 'Remera clara con planeta violeta, anillo ácido y estrellas. Para los que vienen de lejos.', 'indumentaria', NULL, false, 'active', ARRAY['remera', 'espacio', 'blanca']::text[]);
