INSERT INTO products (legacy_id, slug, name, description, category_id, catalog_code, requires_quote, status, tags) VALUES ('p16', 'plancha-dtf-laboratorio', 'Plancha DTF Laboratorio', 'Doce diseños de la casa dispuestos en una plancha de transferencia: criaturas, cohetes, ovnis y más.', 'dtf', NULL, false, 'active', ARRAY['transfer', 'impresión', 'plancha']::text[]);
